/**
 * 자산 URL 대신 SVG 를 인라인으로 둔다.
 * new URL(..., import.meta.url) 은 클라이언트 번들에서만 자산 경로로 치환되고
 * 서버 번들에는 그대로 남아, SSR·프리렌더 HTML 에 file:// 경로가 박힌다.
 * 하이드레이션은 속성 불일치를 고쳐주지 않으므로 초기 진입에서 아이콘이 깨진다.
 */
export function LanguageFlagIcon({ language }: LanguageFlagIconProps) {
  const clipId = useId();
  const hasBorder = language === "ko" || language === "ja";

  return (
    <span
      className={[flagFrame, hasBorder ? flagFrameBorder : ""]
        .filter(Boolean)
        .join(" ")}
      aria-hidden="true"
    >
      <FlagGlyph language={language} clipId={clipId} />
    </span>
  );
}
